#include "migration_status_page.hpp"
#include "migration_status_model.hpp"
#include <QtWidgets>
namespace {
class Page:public QWidget{
public:
MigrationStatusSnapshot provider;MigrationStatusAvailable available;MigrationStatusOpen open;MigrationStatusEvidence evidence;QJsonObject snapshot,entry,response;QJsonArray matches;QMap<QString,QComboBox*> filters;QLineEdit* search;QLabel *header,*count,*message;QListWidget* rows;QStackedWidget* stack;QPlainTextEdit *detail,*proof;QComboBox* refs;QPushButton *previous,*next,*jump,*readEvidence;int page=0;bool restoring=false;QString entryVersion,entryAsOf;
Page(QWidget* parent,MigrationStatusSnapshot s,MigrationStatusAvailable a,MigrationStatusOpen o,MigrationStatusEvidence e):QWidget(parent),provider(s),available(a),open(o),evidence(e){auto layout=new QVBoxLayout(this);stack=new QStackedWidget(this);layout->addWidget(stack);auto main=new QWidget(stack);stack->addWidget(main);auto l=new QVBoxLayout(main);header=new QLabel("迁移状态 · 尚无有效冻结快照",main);header->setTextFormat(Qt::PlainText);header->setWordWrap(true);l->addWidget(header);search=new QLineEdit(main);search->setObjectName("migrationStatusSearch");search->setPlaceholderText("搜索标题、缺口或完整证据记录");l->addWidget(search);auto grid=new QGridLayout;l->addLayout(grid);QStringList keys{"platform","module","implementation","acceptance","externalBlocker"},labels{"平台","模块","实现","验收","外部阻断"};for(int i=0;i<keys.size();++i){auto c=new QComboBox(main);c->setObjectName("migrationStatus_"+keys[i]);filters[keys[i]]=c;grid->addWidget(new QLabel(labels[i],main),i/3*2,i%3);grid->addWidget(c,i/3*2+1,i%3);connect(c,qOverload<int>(&QComboBox::currentIndexChanged),this,[=](int){if(!restoring){page=0;render();}});}count=new QLabel(main);l->addWidget(count);rows=new QListWidget(main);rows->setObjectName("migrationStatusRows");l->addWidget(rows,1);auto actions=new QHBoxLayout;l->addLayout(actions);previous=new QPushButton("上一页",main);next=new QPushButton("下一页",main);auto read=new QPushButton("查看完整缺口和证据",main),refreshButton=new QPushButton("重新读取注入快照",main),exportButton=new QPushButton("导出完整当前快照",main);for(auto b:{previous,next,read,refreshButton,exportButton})actions->addWidget(b);message=new QLabel(this);message->setTextFormat(Qt::PlainText);message->setWordWrap(true);layout->addWidget(message);
auto reader=new QWidget(stack);stack->addWidget(reader);auto dl=new QVBoxLayout(reader);auto back=new QPushButton("返回筛选列表",reader);dl->addWidget(back);detail=new QPlainTextEdit(reader);detail->setReadOnly(true);detail->setObjectName("migrationStatusDetail");dl->addWidget(detail,1);jump=new QPushButton("打开已接入原生功能",reader);dl->addWidget(jump);refs=new QComboBox(reader);dl->addWidget(refs);readEvidence=new QPushButton("读取所选证据",reader);dl->addWidget(readEvidence);
auto evidencePage=new QWidget(stack);stack->addWidget(evidencePage);auto el=new QVBoxLayout(evidencePage);auto evidenceBack=new QPushButton("返回完整审查项",evidencePage);el->addWidget(evidenceBack);proof=new QPlainTextEdit(evidencePage);proof->setReadOnly(true);proof->setObjectName("migrationStatusEvidence");el->addWidget(proof,1);
connect(search,&QLineEdit::textChanged,this,[=]{if(!restoring){page=0;render();}});connect(previous,&QPushButton::clicked,this,[=]{if(page>0){--page;render();}});connect(next,&QPushButton::clicked,this,[=]{if((page+1)*20<matches.size()){++page;render();}});connect(read,&QPushButton::clicked,this,[=]{showRow();});connect(rows,&QListWidget::itemDoubleClicked,this,[=]{showRow();});connect(refreshButton,&QPushButton::clicked,this,[=]{refresh();});connect(back,&QPushButton::clicked,this,[=]{stack->setCurrentIndex(0);});connect(evidenceBack,&QPushButton::clicked,this,[=]{stack->setCurrentIndex(1);});connect(jump,&QPushButton::clicked,this,[=]{guard([=]{fresh();if(!open||!available||!available(entry.value("id").toString(),entry.value("route").toString()))throw std::runtime_error("入口当前未接入；未执行跳转");open(entry.value("id").toString(),entry.value("route").toString());});});connect(readEvidence,&QPushButton::clicked,this,[=]{guard([=]{fresh();if(!evidence||refs->currentText().isEmpty())throw std::runtime_error("没有可解析的证据引用");auto captured=evidence(entry.value("id").toString(),refs->currentText());migrationStatus::bytes(captured);response=captured;proof->setPlainText("宿主返回的证据；版本和可用性以返回元数据为准\n来源："+migrationStatus::field(captured,"source")+"\n时点："+migrationStatus::field(captured,"asOf")+"\n可用："+migrationStatus::field(captured,"available")+"\n说明："+migrationStatus::field(captured,"message")+"\n\n"+migrationStatus::field(captured,"text"));stack->setCurrentIndex(2);});});connect(exportButton,&QPushButton::clicked,this,[=]{guard([=]{if(snapshot.isEmpty())throw std::runtime_error("尚无有效快照");auto bytes=migrationStatus::bytes(snapshot);auto path=QFileDialog::getSaveFileName(this,"导出完整迁移快照","migration-status.json","JSON (*.json)");if(path.isEmpty())return;QSaveFile file(path);if(!file.open(QIODevice::WriteOnly)||file.write(bytes)!=bytes.size()||!file.commit())throw std::runtime_error("导出失败");message->setText("已导出完整注入快照，筛选未删减审查项");});});refresh();}
void guard(std::function<void()> fn){try{fn();}catch(const std::exception& e){message->setText(QString::fromUtf8(e.what()));}}
QJsonObject query()const{QJsonObject q{{"search",search->text()}};for(auto i=filters.begin();i!=filters.end();++i)q[i.key()]=i.value()->currentData().toString();return q;}
void refresh(){guard([=]{if(!provider)throw std::runtime_error("宿主尚未提供迁移快照");auto candidate=migrationStatus::validate(provider());auto old=query();snapshot=candidate;restoring=true;for(auto i=filters.begin();i!=filters.end();++i){auto c=i.value();c->clear();c->addItem("全部","");for(auto v:migrationStatus::options(snapshot,i.key()))c->addItem(v,v);int n=c->findData(old.value(i.key()).toString());c->setCurrentIndex(n<0?0:n);}restoring=false;header->setText(migrationStatus::summary(snapshot));render();message->setText("仅显示宿主注入的冻结快照；没有更新项目状态");});}
void render(){if(snapshot.isEmpty())return;matches=migrationStatus::filter(snapshot,query());page=qBound(0,page,qMax(0,(matches.size()-1)/20));rows->clear();for(int i=page*20;i<qMin(matches.size(),(page+1)*20);++i){auto r=matches[i].toObject();auto item=new QListWidgetItem(migrationStatus::field(r,"id")+" · "+migrationStatus::field(r,"title")+" · "+migrationStatus::field(r,"nativeStatus"),rows);item->setData(Qt::UserRole,r);}count->setText(QString("匹配 %1 / 全量 %2 · 第 %3/%4 页 · 每页20项").arg(matches.size()).arg(snapshot.value("entries").toArray().size()).arg(page+1).arg(qMax(1,(matches.size()+19)/20)));previous->setEnabled(page>0);next->setEnabled((page+1)*20<matches.size());}
void showRow(){guard([=]{if(!rows->currentItem())throw std::runtime_error("先选审查项");entry=rows->currentItem()->data(Qt::UserRole).toJsonObject();entryVersion=migrationStatus::field(snapshot,"version");entryAsOf=migrationStatus::field(snapshot,"asOf");showDetail();});}
void showDetail(){detail->setPlainText("所读冻结版本："+entryVersion+" / "+entryAsOf+"\n"+migrationStatus::detail(entry));refs->clear();refs->addItems(migrationStatus::references(entry));bool enabled=available&&open&&available(entry.value("id").toString(),entry.value("route").toString());jump->setEnabled(enabled);jump->setText(enabled?"打开已接入原生功能":"原生入口未接入（禁用，不代表完成）");readEvidence->setEnabled(evidence&&refs->count()>0);stack->setCurrentIndex(1);}
void fresh(){if(!provider)throw std::runtime_error("当前快照不可核验");auto current=migrationStatus::validate(provider());for(auto v:current.value("entries").toArray()){auto r=v.toObject();if(r.value("id")==entry.value("id")){if(r!=entry)throw std::runtime_error("审查项已变化；请返回并重新读取快照");return;}}throw std::runtime_error("当前快照已缺少该审查项");}
QJsonObject save()const{return {{"filters",query()},{"page",page},{"view",stack->currentIndex()},{"entry",entry},{"entryVersion",entryVersion},{"entryAsOf",entryAsOf},{"response",response},{"listScroll",rows->verticalScrollBar()->value()},{"detailScroll",detail->verticalScrollBar()->value()},{"evidenceScroll",proof->verticalScrollBar()->value()},{"evidenceReference",refs->currentText()}};}
void restore(const QJsonObject& s){guard([=]{restoring=true;auto q=s.value("filters").toObject();search->setText(q.value("search").toString());for(auto i=filters.begin();i!=filters.end();++i){int n=i.value()->findData(q.value(i.key()).toString());i.value()->setCurrentIndex(n<0?0:n);}restoring=false;page=qMax(0,s.value("page").toInt());render();rows->verticalScrollBar()->setValue(s.value("listScroll").toInt());entry=s.value("entry").toObject();entryVersion=migrationStatus::field(s,"entryVersion");entryAsOf=migrationStatus::field(s,"entryAsOf");response=s.value("response").toObject();int view=s.value("view").toInt();if(view>0&&!entry.isEmpty()){showDetail();refs->setCurrentText(s.value("evidenceReference").toString());detail->verticalScrollBar()->setValue(s.value("detailScroll").toInt());if(view==2){proof->setPlainText("宿主返回的证据；版本以元数据为准\n来源："+migrationStatus::field(response,"source")+"\n时点："+migrationStatus::field(response,"asOf")+"\n可用："+migrationStatus::field(response,"available")+"\n说明："+migrationStatus::field(response,"message")+"\n\n"+migrationStatus::field(response,"text"));stack->setCurrentIndex(2);proof->verticalScrollBar()->setValue(s.value("evidenceScroll").toInt());}}QTimer::singleShot(0,this,[=]{rows->verticalScrollBar()->setValue(s.value("listScroll").toInt());detail->verticalScrollBar()->setValue(s.value("detailScroll").toInt());proof->verticalScrollBar()->setValue(s.value("evidenceScroll").toInt());});});}
};
}
QWidget* migrationStatusPage(QWidget*p,MigrationStatusSnapshot s,MigrationStatusAvailable a,MigrationStatusOpen o,MigrationStatusEvidence e){return new Page(p,s,a,o,e);}
bool migrationStatusBack(QWidget*w){auto p=dynamic_cast<Page*>(w);if(!p||p->stack->currentIndex()==0)return false;p->stack->setCurrentIndex(p->stack->currentIndex()-1);return true;}
QJsonObject migrationStatusSaveState(QWidget*w){auto p=dynamic_cast<Page*>(w);return p?p->save():QJsonObject{};}
void migrationStatusRestoreState(QWidget*w,const QJsonObject&s){if(auto p=dynamic_cast<Page*>(w))p->restore(s);}




